script:
// ดึงชื่อจาก User ที่ login อยู่
frappe.ui.form.on('Hospital Receipt', {
    onload: function(frm) {
        if (frm.is_new()) {
            // รับอีเมลของผู้ใช้ปัจจุบัน
            let user_email = frappe.session.user;

            // เรียกใช้ฟังก์ชันฝั่งเซิร์ฟเวอร์เพื่อรับข้อมูลผู้ใช้
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'User',
                    name: user_email
                },
                callback: function(response) {
                    if (response.message) {
                        let user_doc = response.message;
                        // เข้าถึงฟิลด์ full_name
                        let full_name = user_doc.full_name;
                        
                        // ตั้งค่าในแบบฟอร์มกำหนดการทำงาน
                        frm.set_value('fullname', full_name);
                        
                        // รีเฟรชฟิลด์เพื่อให้แน่ใจว่ามีการอัปเดตแล้ว
                        frm.refresh_field('fullname');
                       
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Hospital Receipt', {
    fullname: function(frm) {
        frappe.call({
            method: "frappe.client.get_value",
            args: { 
                doctype: "Personnel",
                fieldname: ["department"],
                filters: { name: frm.doc.fullname },
            },
            callback: function(r) {
                if (r.message) {
                    cur_frm.set_value("department", r.message.department);
                    frm.trigger('onload'); // เรียก onload ใหม่หลังจากดึงข้อมูล
                }
            }
        });
    }
});


frappe.ui.form.on('Hospital Receipt', {
    retrieve_data: function(frm) {
        const start_date = frm.doc.receipt_start_date;
        const end_date = frm.doc.receipt_end_date;

        if (!start_date || !end_date) {
            frappe.msgprint("กรุณาระบุวันที่เริ่มต้นและสิ้นสุด");
            return;
        }

        // 🌀 แสดง spinner ตอนเริ่มโหลด
        frm.set_df_property("display", "hidden", false);
        frm.fields_dict["display"].$wrapper.html(`
            <div style="color: #555; font-size: 14px;">
                <i class="fa fa-spinner fa-spin" style="margin-right: 5px;"></i>
                กำลังโหลดข้อมูล...
            </div>
        `);

        frappe.call({
            method: "erpnext.hospital_receipt.get_hospital_receipt",
            args: {
                receipt_start_date: start_date,
                receipt_end_date: end_date
            },
            callback: function(r) {
                if (r.message) {
                    frm.clear_table("hospital_receipt_table");

                    r.message.forEach(function(row) {
                        let new_row = frm.add_child("hospital_receipt_table");
                        new_row.posting_date = row.Receipt_date;
                        new_row.receipt_number = row.Receipt_name;
                        new_row.fullname = row.Fullname;
                        new_row.amount_of_money = row.Amountofmoney;
                        new_row.payment_type = row.Note_;
                        new_row.eyeglasses_lens = row.Eyeglasses_Lens;
                    });

                    frm.refresh_field("hospital_receipt_table");

                    // ✅ แสดงข้อความเสร็จสมบูรณ์
                    frm.fields_dict["display"].$wrapper.html(`
                        <div style="color: green; font-size: 15px;">
                            <i class="fa fa-check-circle" style="margin-right: 5px;"></i>
                            ดึงข้อมูลสำเร็จ
                        </div>
                    `);
                } else {
                    frm.fields_dict["display"].$wrapper.html(`
                        <div style="color: orange; font-size: 15px;">
                            <i class="fa fa-exclamation-circle" style="margin-right: 5px;"></i>
                            ไม่พบข้อมูลในช่วงวันที่ที่เลือก
                        </div>
                    `);
                }
            },
            error: function() {
                frm.fields_dict["display"].$wrapper.html(`
                    <div style="color: red; font-size: 14px;">
                        <i class="fa fa-times-circle" style="margin-right: 5px;"></i>
                        เกิดข้อผิดพลาดในการดึงข้อมูล
                    </div>
                `);
            }
        });
    }
});

frappe.ui.form.on('Hospital Receipt', {
    validate: function(frm) {
        let total_money = 0;

        // รวมค่าจากตาราง
        frm.doc.hospital_receipt_table.forEach(row => {
            total_money += row.amount_of_money || 0;
        });

        frm.set_value('sum_of_money', total_money);
    }
});


frappe.ui.form.on('Hospital Receipt', {
    validate: function(frm) {
        let row_count = 0;

        // รวมค่าจากตาราง
        frm.doc.hospital_receipt_table.forEach(row => {
            row_count = frm.doc.hospital_receipt_table.length;
        });

        frm.set_value('number_items', row_count);
    }
});
